mapper.select:
SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_ABBR text, T2.CUSTOMER_NAME, T1.FINPROD_ID FROM FIN_PRODUCT T1 LEFT JOIN MST_CUSTOMER_INFO T2 ON T1.FINANCIER = T2.CUSTOMER_ID WHERE 1=1 AND FINPROD_TYPE2=#{FINPROD_TYPE_TG_F37} AND FINPROD_MARKET_ID IS NOT NULL
AND (FINPROD_MARKET_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%')
)
AND FINPROD_MARKET_ID = #{initValue}

mapper.delete:
delete from FIN_PRODUCT_VALUATION
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and VAL_DATE = #{valDate,jdbcType=DATE}
  and FINPROD_TYPE2  = #{finprodType2,jdbcType=VARCHAR}
